        .with_constructor(default_ctr())
        .deploy()
        .await?
        .contract_address;
    let contract = Erc20::new(contract_addr, &alice.wallet);

    let name = contract.name().call().await?.name;
    let symbol = contract.symbol().call().await?.symbol;
