        let addresses = vec![];
        let data = vec![Bytes::new()];
        let err = contract
            .multicall(addresses, data)
            .call()
            .await
            .unwrap_err()
            .as_decoded_interface_error::<IMultiCall::IMultiCallErrors>()
            .unwrap();
        assert!(matches!(
            err,
            IMultiCall::IMultiCallErrors::ArraySizeNotMatch(..)
        ));

        Ok(())
    }
}
