const SEPARATOR: &str = "::";

#[derive(Debug)]
pub struct FunctionReport {
    sig: String,
    gas: u128,
}

impl FunctionReport {
    pub(crate) fn new(
        receipt: (&str, AnyTransactionReceipt),
