    fn create_command(&self, wasm_path: &str) -> Command {
        let mut command = Command::new("cargo");
        command
            .args(["stylus", "deploy"])
            .args(["-e", &self.rpc_url])
            .args(["--private-key", &self.private_key])
            .args(["--wasm-file", wasm_path])
