use crate::report::{ContractReport, FunctionReport};

sol!(
    #[sol(rpc)]
   contract PoseidonExample {
        #[derive(Debug)]
        function hash(uint256[2] memory inputs) external view returns (uint256 hash);
    }
);

pub async fn bench() -> eyre::Result<ContractReport> {
    let reports = run().await?;
    let report = reports
        .into_iter()
        .try_fold(ContractReport::new("Sol:Poseidon"), ContractReport::add)?;

    Ok(report)
}

pub async fn run() -> eyre::Result<Vec<FunctionReport>> {
    let alice = Account::new().await?;
    let alice_wallet = ProviderBuilder::new()
        .network::<AnyNetwork>()
        .with_recommended_fillers()
        .wallet(EthereumWallet::from(alice.signer.clone()))
        .on_http(alice.url().parse()?);

    let contract_addr = deploy(&alice).await?;

    let contract = PoseidonExample::new(contract_addr, &alice_wallet);

    #[rustfmt::skip]
    let receipts = vec![
        (PoseidonExample::hashCall::SIGNATURE, receipt!(contract.hash([uint!(123_U256), uint!(123456_U256)]))?),
    ];

    receipts
        .into_iter()
        .map(FunctionReport::new)
        .collect::<eyre::Result<Vec<_>>>()
}

pub async fn deploy(account: &Account) -> eyre::Result<Address> {
    let contract = PoseidonT3::deploy(&account.wallet).await?;
    Ok(*contract.address())
}

