//! Shared Alloy and Stylus SDK devnet support for example integration tests.

use std::{fmt::Debug, path::PathBuf};

use alloy::{
    network::{Ethereum, EthereumWallet, TransactionBuilder},
    primitives::{utils::parse_ether, Address, Bytes, U256},
    providers::{DynProvider, Provider, ProviderBuilder},
    rpc::types::{TransactionReceipt, TransactionRequest},
    signers::{local::PrivateKeySigner, Signature, Signer},
    sol_types::{SolError, SolEvent},
};
use eyre::{eyre, Result, WrapErr};
use stylus_tools::{devnet::Node, Activator, Deployer};
use tokio::sync::{Mutex, MutexGuard, OnceCell};

/// Alloy HTTP wallet provider used by the test accounts and Solidity mocks.
pub type Wallet = DynProvider<Ethereum>;

static DEVNET: OnceCell<Node> = OnceCell::const_new();
static TEST_LOCK: Mutex<()> = Mutex::const_new(());

async fn node() -> Result<&'static Node> {
    DEVNET.get_or_try_init(|| async { Node::new().await }).await
}

/// Holds the per-test lock and lazily starts one Nitro devnet per test binary.
///
/// Tests use the same devnet sequentially and deploy fresh contracts, which
/// keeps their state independent without starting a Docker container per test.
pub struct TestContext {
    _guard: MutexGuard<'static, ()>,
}

impl TestContext {
    /// Acquire the serial test lock and start the SDK devnet on first use.
    pub async fn new() -> Result<Self> {
        let guard = TEST_LOCK.lock().await;
        node().await?;
        Ok(Self { _guard: guard })
    }
}

/// A funded local signer and provider connected to the test devnet.
#[derive(Clone)]
pub struct Account {
    /// Local signing key.
    pub signer: PrivateKeySigner,
    /// Alloy provider and wallet for this account.
    pub wallet: Wallet,
    rpc: String,
}

impl Account {
    /// Generate an account and fund it with 100 ETH from the devnet owner.
    pub async fn new() -> Result<Self> {
        let node = node().await?;
        let signer = PrivateKeySigner::random();
        let address = signer.address();
        let owner = node.create_provider().await?;
        owner
            .send_transaction(
                TransactionRequest::default()
                    .with_to(address)
                    .with_value(parse_ether("100")?),
            )
            .await?
            .watch()
            .await?;

        let wallet = ProviderBuilder::new()
            .wallet(EthereumWallet::from(signer.clone()))
            .connect_http(node.rpc().parse()?)
            .erased();

        Ok(Self { signer, wallet, rpc: node.rpc().to_owned() })
    }

    /// Return the account's private key as hex without a `0x` prefix.
    #[must_use]
    pub fn pk(&self) -> String {
        alloy::hex::encode(self.signer.to_bytes())
    }

    /// Return the account address.
    #[must_use]
    pub fn address(&self) -> Address {
        self.signer.address()
    }

    /// Return the RPC endpoint used by this account.
    #[must_use]
    pub fn url(&self) -> &str {
        &self.rpc
    }

    /// Sign a hash with the local account.
    pub async fn sign_hash(&self, hash: &alloy::primitives::B256) -> Signature {
        self.signer.sign_hash(hash).await.expect("local signing should succeed")
    }

    /// Sign a message with the local account.
    pub async fn sign_message(&self, message: &[u8]) -> Signature {
        self.signer
            .sign_message(message)
            .await
            .expect("local signing should succeed")
    }

    /// Create a deployer for a Stylus example contract.
    #[must_use]
    pub fn as_deployer(&self) -> TestDeployer {
        TestDeployer {
            rpc: self.rpc.clone(),
            private_key: format!("0x{}", self.pk()),
            directory: PathBuf::from(env!("CARGO_MANIFEST_DIR")),
            constructor_args: None,
        }
    }
}

/// A contract receipt with the deployed Stylus address and deployment logs.
#[derive(Debug)]
pub struct Receipt {
    /// Receipt for the StylusDeployer transaction.
    pub inner: TransactionReceipt,
    /// Address of the deployed Stylus contract.
    pub contract_address: Address,
}

/// Stylus deployer wrapper for the example test fixtures.
pub struct TestDeployer {
    rpc: String,
    private_key: String,
    directory: PathBuf,
    constructor_args: Option<Vec<String>>,
}

impl TestDeployer {
    /// Set constructor arguments. The SDK reads the constructor signature from
    /// the selected crate's exported ABI.
    #[must_use]
    pub fn with_constructor(mut self, constructor: Constructor) -> Self {
        self.constructor_args = Some(constructor.args);
        self
    }

    /// Select a sibling example crate as the deployment target.
    #[must_use]
    pub fn with_example_name(mut self, example_name: &str) -> Self {
        self.directory = self
            .directory
            .parent()
            .expect("example manifest directory has a parent")
            .join(example_name);
        self
    }

    /// Select an explicit directory containing a Stylus contract crate.
    #[must_use]
    pub fn with_directory(mut self, directory: impl Into<PathBuf>) -> Self {
        self.directory = directory.into();
        self
    }

    /// Deploy and activate the configured Stylus example.
    pub async fn deploy(self) -> Result<Receipt> {
        let directory = self.directory.to_string_lossy().into_owned();
        let deployment = match self.constructor_args {
            Some(args) => Deployer::builder()
                .rpc(self.rpc.clone())
                .private_key(self.private_key.clone())
                .dir(directory.clone())
                .constructor_args(args)
                .build()
                .deploy(),
            None => Deployer::builder()
                .rpc(self.rpc.clone())
                .private_key(self.private_key.clone())
                .dir(directory.clone())
                .build()
                .deploy(),
        }
        .map_err(map_initialization_error)?;

        let (contract_address, tx_hash, _) = deployment;
        Activator::builder()
            .rpc(self.rpc.clone())
            .private_key(self.private_key.clone())
            .contract_address(contract_address.to_string())
            .dir(directory)
            .build()
            .activate()?;

        let provider = ProviderBuilder::new()
            .wallet(EthereumWallet::from(
                self.private_key
                    .parse::<PrivateKeySigner>()
                    .wrap_err("invalid deployer private key")?,
            ))
            .connect_http(self.rpc.parse()?)
            .erased();
        let inner =
            provider.get_transaction_receipt(tx_hash).await?.ok_or_else(
                || eyre!("deployment transaction receipt was not found"),
            )?;

        Ok(Receipt { inner, contract_address })
    }
}

fn map_initialization_error(error: eyre::Report) -> eyre::Report {
    let initialization_selector = stylus_sdk::function_selector!(
        "ContractInitializationError",
        Address,
        Bytes
    );
    let selector = alloy::hex::encode(initialization_selector);
    let message = error.to_string().to_ascii_lowercase();
    if message.contains(&selector)
        || message.contains("contractinitializationerror")
    {
        eyre::Report::new(ContractInitializationError)
    } else {
        error
    }
}

/// Error returned by the Stylus deployer when a constructor reverts.
#[derive(Debug)]
pub struct ContractInitializationError;

impl std::fmt::Display for ContractInitializationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("ContractInitializationError")
    }
}

impl std::error::Error for ContractInitializationError {}

/// Constructor argument data used by [`TestDeployer`].
pub struct Constructor {
    /// Constructor signature retained for compatibility with old test helpers.
    pub signature: String,
    /// Stringified constructor values passed to `cargo stylus deploy`.
    pub args: Vec<String>,
}

/// Convert an ABI value to the format accepted by `cargo stylus deploy`.
pub trait AbiTypeToString {
    /// Convert the value to a deployer argument.
    fn abi_type_to_string(&self) -> String;
}

macro_rules! impl_to_arg_string {
    ($($ty:ty),* $(,)?) => {
        $(
            impl AbiTypeToString for $ty {
                fn abi_type_to_string(&self) -> String {
                    self.to_string()
                }
            }
        )*
    };
}

impl_to_arg_string!(Address, U256, u64, u8, String);

impl AbiTypeToString for alloy::primitives::aliases::U8 {
    fn abi_type_to_string(&self) -> String {
        self.to_string()
    }
}

impl AbiTypeToString for Bytes {
    fn abi_type_to_string(&self) -> String {
        format!("0x{}", alloy::hex::encode(self))
    }
}

macro_rules! constructor {
    () => {{
        $crate::test_support::Constructor { signature: "constructor()".to_owned(), args: vec![] }
    }};
    ($first:expr $(, $rest:expr)* $(,)?) => {{
        $crate::test_support::Constructor {
            // The SDK derives this signature from the selected package's ABI.
            signature: {
                fn abi_name<T: stylus_sdk::abi::AbiType>(_: T) -> &'static str {
                    T::ABI.as_str()
                }

                let params = vec![abi_name($first) $(, abi_name($rest))*];
                format!("constructor({})", params.join(","))
            },
            args: vec![
                $crate::test_support::AbiTypeToString::abi_type_to_string(&$first)
                $(, $crate::test_support::AbiTypeToString::abi_type_to_string(&$rest))*
            ],
        }
use std::{
    fs,
    path::{Path, PathBuf},
    process::Command,
};

use crate::test_support::{Account, Constructor};
use alloy::primitives::Address;
use alloy_primitives::U128;
use eyre::{ContextCompat, WrapErr};
use serde::Deserialize;

#[path = "../../examples/test-support/mod.rs"]
pub mod test_support;

pub mod access_control;
pub mod erc1155;
pub mod erc1155_metadata_uri;
pub mod erc1155_supply;
pub mod erc20;
pub mod erc721;
pub mod merkle_proofs;
pub mod ownable;
pub mod pedersen;
pub mod poseidon;
pub mod poseidon_asm_sol;
pub mod poseidon_sol;
pub mod report;
pub mod vesting_wallet;

#[derive(Debug, Deserialize)]
struct ArbOtherFields {
    #[serde(rename = "gasUsedForL1")]
    gas_used_for_l1: U128,
    #[allow(dead_code)]
    #[serde(rename = "l1BlockNumber")]
    l1_block_number: String,
}

/// Optimisation options for the contract.
///
/// Cache or cache optimized WASM.
#[derive(Clone)]
pub enum Opt {
    None,
    Cache,
    CacheWasmOpt,
}

async fn deploy(
    account: &Account,
    contract_name: &str,
    constructor: Option<Constructor>,
    opt: Opt,
) -> eyre::Result<Address> {
    let workspace_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .context("benches package should be inside a workspace")?
        .to_path_buf();
    let contract_dir = workspace_dir.join("examples").join(contract_name);

    // The SDK's deployer uses the contract crate's Stylus.toml. Enable the
    // SDK's pinned optimizer only for the optimized benchmark pass and restore
    // any existing config as soon as deployment completes.
    let _wasm_opt = match opt {
        Opt::CacheWasmOpt => Some(WasmOptConfig::enable(&contract_dir)?),
        Opt::None | Opt::Cache => None,
    };

    let mut deployer = account.as_deployer().with_directory(contract_dir);
    if let Some(constructor) = constructor {
        deployer = deployer.with_constructor(constructor);
    }
    let address = deployer.deploy().await?.contract_address;

    match opt {
        Opt::Cache | Opt::CacheWasmOpt => {
            cache_contract(account, address, 0)?;
        }
        Opt::None => {}
    }

    Ok(address)
}

/// Try to cache a contract on the stylus network.
/// Already cached contracts won't be cached, and this function will not return
/// an error.
/// Output will be forwarded to the child process.
fn cache_contract(
    account: &Account,
    contract_addr: Address,
    bid: u32,
) -> eyre::Result<()> {
    // We don't need a status code.
    // Since it is not zero when the contract is already cached.
    Command::new("cargo")
        .args(["stylus", "cache", "bid"])
        .args(["-e", account.url()])
        .args(["--private-key", &format!("0x{}", account.pk())])
        .arg(contract_addr.to_string())
        .arg(bid.to_string())
        .status()
        .context("failed to execute `cargo stylus cache bid` command")?;
    Ok(())
}

struct WasmOptConfig {
    path: PathBuf,
    original: Option<Vec<u8>>,
}

impl WasmOptConfig {
    fn enable(contract_dir: &Path) -> eyre::Result<Self> {
        let path = contract_dir.join("Stylus.toml");
        let original = path.exists().then(|| fs::read(&path)).transpose()?;
        let existing =
            original.as_deref().map(std::str::from_utf8).transpose()?;
        let existing = existing.unwrap_or_default();
        eyre::ensure!(
            !existing.lines().any(|line| line.trim() == "[wasm-opt]"),
            "{} already has a [wasm-opt] table; update the benchmark config to avoid replacing it",
            path.display()
        );

        let config = format!(
            "{existing}\n[wasm-opt]\nversion = \"116\"\nflags = [\"-O3\"]\n"
        );
        fs::write(&path, config)?;

        Ok(Self { path, original })
    }
}

impl Drop for WasmOptConfig {
    fn drop(&mut self) {
        match self.original.take() {
            Some(contents) => {
                let _ = fs::write(&self.path, contents);
            }
            None => {
                let _ = fs::remove_file(&self.path);
            }
        }
    }
}
use alloy::{
    network::EthereumWallet, primitives::Address, providers::ProviderBuilder,
    signers::local::PrivateKeySigner, sol,
};
use std::path::PathBuf;
use stylus_tools::{Activator, Deployer};

sol!(
    #[sol(rpc)]
    contract BasicToken {
        constructor(string memory name_, string memory symbol_);

        function name() external view returns (string name);
        function symbol() external view returns (string symbol);
    }
);

const RPC_URL: &str = "https://sepolia-rollup.arbitrum.io/rpc";
const PRIVATE_KEY: &str = "your private key";
const TOKEN_NAME: &str = "Test Token";
const TOKEN_SYMBOL: &str = "TTK";

#[tokio::main]
async fn main() {
    // WARNING: Please use a more secure method for storing your privaket key
    // than a string at the top of this file. The following code is for testing
    // purposes only.
    let signer = PRIVATE_KEY
        .parse::<PrivateKeySigner>()
        .expect("should parse the private key");
    let wallet = EthereumWallet::from(signer.clone());
    let rpc_url = RPC_URL.parse().expect("should parse rpc url");
    let provider = ProviderBuilder::new().wallet(wallet).connect_http(rpc_url);

    let contract_address = deploy(&signer);

    let contract = BasicToken::new(contract_address, &provider);

    let call_result = contract.name().call().await.unwrap();
    assert_eq!(call_result.name, TOKEN_NAME.to_owned());

    let call_result = contract.symbol().call().await.unwrap();
    assert_eq!(call_result.symbol, TOKEN_SYMBOL.to_owned());
}

/// Deploy a `BasicToken` contract to `RPC_URL` using `cargo-stylus`.
fn deploy(signer: &PrivateKeySigner) -> Address {
    let contract_dir =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../token");
    let private_key = format!("0x{}", alloy::hex::encode(signer.to_bytes()));

    let (address, _, _) = Deployer::builder()
        .rpc(RPC_URL)
        .private_key(private_key.clone())
        .dir(contract_dir.to_string_lossy().into_owned())
        .constructor_args(vec![TOKEN_NAME.to_owned(), TOKEN_SYMBOL.to_owned()])
        .build()
        .deploy()
        .expect("contract should be deployed");

    Activator::builder()
        .rpc(RPC_URL)
        .private_key(private_key)
        .contract_address(address.to_string())
        .dir(contract_dir.to_string_lossy().into_owned())
        .build()
        .activate()
        .expect("contract should be activated");

    address
}

