/// Optimisation options for the contract.
///
/// Cache or cache optimized WASM.
#[derive(Clone)]
pub enum Opt {
    None,
    Cache,
    CacheWasmOpt,
}

async fn deploy(
    account: &Account,
    contract_name: &str,
    constructor: Option<Constructor>,
    opt: Opt,
) -> eyre::Result<Address> {
    let workspace_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .context("benches package should be inside a workspace")?
        .to_path_buf();
    let contract_dir = workspace_dir.join("examples").join(contract_name);

    // The SDK's deployer uses the contract crate's Stylus.toml. Enable the
    // SDK's pinned optimizer only for the optimized benchmark pass and restore
    // any existing config as soon as deployment completes.
    let _wasm_opt = match opt {
        Opt::CacheWasmOpt => Some(WasmOptConfig::enable(&contract_dir)?),
        Opt::None | Opt::Cache => None,
    };

    let mut deployer = account.as_deployer().with_directory(contract_dir);
    if let Some(constructor) = constructor {
        deployer = deployer.with_constructor(constructor);
    }
    let address = deployer.deploy().await?.contract_address;

    match opt {
        Opt::Cache | Opt::CacheWasmOpt => {
            cache_contract(account, address, 0)?;
        }
        Opt::None => {}
    }

    Ok(address)
}

/// Try to cache a contract on the stylus network.
/// Already cached contracts won't be cached, and this function will not return
/// an error.
/// Output will be forwarded to the child process.
fn cache_contract(
    account: &Account,
    contract_addr: Address,
    bid: u32,
) -> eyre::Result<()> {
    // We don't need a status code.
    // Since it is not zero when the contract is already cached.
    Command::new("cargo")
        .args(["stylus", "cache", "bid"])
        .args(["-e", account.url()])
        .args(["--private-key", &format!("0x{}", account.pk())])
        .arg(contract_addr.to_string())
        .arg(bid.to_string())
        .status()
        .context("failed to execute `cargo stylus cache bid` command")?;
    Ok(())
}

struct WasmOptConfig {
    path: PathBuf,
    original: Option<Vec<u8>>,
}

impl WasmOptConfig {
    fn enable(contract_dir: &Path) -> eyre::Result<Self> {
        let path = contract_dir.join("Stylus.toml");
        let original = path.exists().then(|| fs::read(&path)).transpose()?;
        let existing =
            original.as_deref().map(std::str::from_utf8).transpose()?;
        let existing = existing.unwrap_or_default();
        eyre::ensure!(
            !existing.lines().any(|line| line.trim() == "[wasm-opt]"),
            "{} already has a [wasm-opt] table; update the benchmark config to avoid replacing it",
            path.display()
        );

        let config = format!(
            "{existing}\n[wasm-opt]\nversion = \"116\"\nflags = [\"-O3\"]\n"
        );
        fs::write(&path, config)?;

        Ok(Self { path, original })
    }
}

impl Drop for WasmOptConfig {
    fn drop(&mut self) {
        match self.original.take() {
            Some(contents) => {
                let _ = fs::write(&self.path, contents);
            }
            None => {
                let _ = fs::remove_file(&self.path);
            }
        }
    }
}
use alloy::{
    network::EthereumWallet, primitives::Address, providers::ProviderBuilder,
    signers::local::PrivateKeySigner, sol,
};
use std::path::PathBuf;
use stylus_tools::{Activator, Deployer};

sol!(
    #[sol(rpc)]
    contract BasicToken {
        constructor(string memory name_, string memory symbol_);

        function name() external view returns (string name);
        function symbol() external view returns (string symbol);
    }
);

const RPC_URL: &str = "https://sepolia-rollup.arbitrum.io/rpc";
const PRIVATE_KEY: &str = "your private key";
const TOKEN_NAME: &str = "Test Token";
const TOKEN_SYMBOL: &str = "TTK";

#[tokio::main]
async fn main() {
    // WARNING: Please use a more secure method for storing your privaket key
    // than a string at the top of this file. The following code is for testing
    // purposes only.
    let signer = PRIVATE_KEY
        .parse::<PrivateKeySigner>()
        .expect("should parse the private key");
    let wallet = EthereumWallet::from(signer.clone());
    let rpc_url = RPC_URL.parse().expect("should parse rpc url");
    let provider = ProviderBuilder::new().wallet(wallet).connect_http(rpc_url);

    let contract_address = deploy(&signer);

    let contract = BasicToken::new(contract_address, &provider);

    let call_result = contract.name().call().await.unwrap();
    assert_eq!(call_result.name, TOKEN_NAME.to_owned());

    let call_result = contract.symbol().call().await.unwrap();
    assert_eq!(call_result.symbol, TOKEN_SYMBOL.to_owned());
}

/// Deploy a `BasicToken` contract to `RPC_URL` using `cargo-stylus`.
fn deploy(signer: &PrivateKeySigner) -> Address {
    let contract_dir =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../token");
    let private_key = format!("0x{}", alloy::hex::encode(signer.to_bytes()));

    let (address, _, _) = Deployer::builder()
        .rpc(RPC_URL)
        .private_key(private_key.clone())
        .dir(contract_dir.to_string_lossy().into_owned())
        .constructor_args(vec![TOKEN_NAME.to_owned(), TOKEN_SYMBOL.to_owned()])
        .build()
        .deploy()
        .expect("contract should be deployed");

    Activator::builder()
        .rpc(RPC_URL)
        .private_key(private_key)
        .contract_address(address.to_string())
        .dir(contract_dir.to_string_lossy().into_owned())
        .build()
        .activate()
        .expect("contract should be activated");

    address
}

