use std::{env, path::Path};

use alloy::{primitives::Address, providers::Provider};
use bytesize::ByteSize;

use super::chain::ChainConfig;
use crate::{
    core::{
        activation::{self, ActivationConfig},
        build::{build_contract, BuildConfig},
