    gas: u128,
}

impl FunctionReport {
    pub(crate) fn new(
        receipt: (&str, AnyTransactionReceipt),
    ) -> eyre::Result<Self> {
        Ok(FunctionReport {
            sig: receipt.0.to_owned(),
