thread_local! {
    static LAST_TRANSACTION: RefCell<Option<(TestVM, VMState)>> = const { RefCell::new(None) };
    static CONTRACT_ADDRESSES: RefCell<Vec<Address>> = const { RefCell::new(Vec::new()) };
    static CALL_DEPTH: Cell<usize> = const { Cell::new(0) };
