        proxy: Contract<BeaconProxyExample>,
        beacon: Contract<Beacon>,
        erc20: Contract<Erc20Example>,
        alice: Address,
        bob: Address,
    ) {
        beacon.sender(alice).constructor(erc20.address());

        proxy
            .sender(alice)
