    fn default() -> Self {
        Self {
            storage: HashMap::new(),
            msg_sender: DEFAULT_SENDER,
            contract_address: DEFAULT_CONTRACT_ADDRESS,
            chain_id: DEFAULT_CHAIN_ID,
            reentrant: false,
