    pub deploy_returns: HashMap<DeploymentWithSalt, DeploymentReturn>,
    pub emitted_logs: Vec<(Vec<B256>, Vec<u8>)>,
    pub provider: Option<RPCProvider>,
    pub return_data: Vec<u8>,
}

