import difflib,re,subprocess

def extract(source, attr):
    rows=[]
    for m in re.finditer(re.escape(attr),source):
        fm=re.search(r'\b(?:async\s+)?fn\s+(\w+)\s*\(',source[m.end():m.end()+2000])
        if not fm: continue
        fn=source[m.end()+fm.start():]
        name=fm.group(1)
        # Find opening brace after signature; signature has no brace-bearing type syntax here.
        op=fn.find('{')
        if op<0: continue
        # Rust-aware-ish brace scan (comments, quoted strings, chars, raw strings).
        i=op; depth=0; state='normal'; rawhash=0; escaped=False; blockdepth=0
        while i<len(fn):
            c=fn[i]; n=fn[i+1] if i+1<len(fn) else ''
            if state=='normal':
                if c=='/' and n=='/': state='line'; i+=2; continue
                if c=='/' and n=='*': state='block'; blockdepth=1; i+=2; continue
                if c=='r':
                    j=i+1
                    while j<len(fn) and fn[j]=='#': j+=1
                    if j<len(fn) and fn[j]=='"': rawhash=j-(i+1); state='raw'; i=j+1; continue
                if c=='"': state='string'; i+=1; continue
                if c=="'":
                    # lifetime vs char: only treat as char if a closing quote occurs soon.
                    j=i+1; esc=False; found=False
                    while j<min(len(fn),i+8) and fn[j]!='\n':
                        if fn[j]=="'" and not esc: found=True; break
                        if fn[j]=='\\' and not esc: esc=True
                        else: esc=False
                        j+=1
                    if found: state='char'; i+=1; continue
                if c=='{': depth+=1
                elif c=='}':
                    depth-=1
                    if depth==0:
                        body=fn[op+1:i]
                        rows.append((name,body,source.count('\n',0,m.start())+1))
                        break
            elif state=='line':
                if c=='\n': state='normal'
            elif state=='block':
                if c=='/' and n=='*': blockdepth+=1; i+=2; continue
                if c=='*' and n=='/':
                    blockdepth-=1; i+=2
                    if blockdepth==0: state='normal'
                    continue
            elif state=='string' or state=='char':
                if escaped: escaped=False
                elif c=='\\': escaped=True
                elif (state=='string' and c=='"') or (state=='char' and c=="'"): state='normal'
            elif state=='raw':
                if c=='"' and fn[i+1:i+1+rawhash]=='#'*rawhash:
                    i += 1+rawhash; state='normal'; continue
            i+=1
    return rows

def norm(body):
    body=re.sub(r'let\s+_test_context\s*=\s*crate::test_support::TestContext::new\(\)\.await\?\s*;','',body)
    body=re.sub(r'let\s+\w+\s*=\s*crate::test_support::Account::new\(\)\.await\?\s*;','',body)
    # Drop line comments, preserving string content approximately.
    body='\n'.join(line.split('//',1)[0] for line in body.splitlines())
    return re.findall(r'r#*".*?"#*|"(?:\\.|[^"\\])*"|[A-Za-z_][A-Za-z0-9_]*|(?:==|!=|<=|>=|=>|::|->|&&|\|\||\.\.|[[:punct:]])',body,re.S)

old={}
files=subprocess.check_output(['git','grep','-F','-l','#[e2e::test]','v0.3.0','--','examples'],text=True).splitlines()
for f in files:
    path=f.split(':',1)[1]; src=subprocess.check_output(['git','show',f'v0.3.0:{path}'],text=True)
    pkg=path.split('/')[1]
    for name,body,line in extract(src,'#[e2e::test]'):
        old.setdefault((pkg,name),[]).append((path,line,norm(body)))
new={}
for path in subprocess.check_output(['rg','--files','examples'],text=True).splitlines():
