const r = await tools.exec_command({cmd:"rg -n '#\[tokio::test\]' examples --glob '*.rs' | wc -l && python3 - <<'PY'
from pathlib import Path
import re
files=list(Path('examples').rglob('*.rs'))
files=[p for p in files if '/tests/' in str(p)]
counts={}
total=0
for p in files:
 s=p.read_text(); n=len(re.findall(r'#\[tokio::test\]',s))
 if n: counts[str(p).split('/')[1]]=counts.get(str(p).split('/')[1],0)+n; total+=n
print('test attrs:',total)
for p,n in sorted(counts.items()): print(p,n)
PY","workdir":"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:3000}); text(r.output);

