const r = await tools.exec_command({cmd:"python3 - <<'PY'
import os,re
paths=['/tmp/oz-e2e-full.log','/tmp/oz-e2e-full2.log','/tmp/oz-e2e-continuation.log','/tmp/oz-e2e-resume.log','/tmp/oz-e2e-final.log','/tmp/oz-e2e-tail.log','/tmp/oz-e2e-end.log']
paths.sort(key=os.path.getmtime)
latest={}
for path in paths:
    package=None; attempt=None
    for line in open(path):
        m=re.match(r'\[(\d+)/30\] (.+)',line)
        if m:
            if package and attempt is not None and (attempt['passed']+attempt['failed']): latest[package]=attempt
            package=m.group(2).strip(); attempt={'passed':0,'failed':0,'failed_names':[],'log':os.path.basename(path)}
            continue
        if line.startswith('Running the crypto-erc20 template activation smoke test.'):
            package=None; attempt=None; continue
        m=re.match(r'test (.+) \.\.\. (ok|FAILED)$',line.strip())
        if m and package and attempt:
            if m.group(2)=='ok': attempt['passed']+=1
            else:
                attempt['failed']+=1; attempt['failed_names'].append(m.group(1))
    if package and attempt is not None and (attempt['passed']+attempt['failed']): latest[package]=attempt
print('packages',len(latest))
for pkg,x in latest.items(): print(f"{pkg}: {x['passed']} pass, {x['failed']} fail [{x['log']}]")
